# Experiment only (do not merge): #107 experiment 1. Zuul does not capture pod console output of the run
# playbook except the final stdout, so the pod-side placement checks are printed in the pytest summary.
import base64, os, subprocess

_SCRIPT = ""


def pytest_terminal_summary(terminalreporter):
    if os.environ.get("PYTEST_XDIST_WORKER"):
        return
    out = subprocess.run(["bash", "-c", base64.b64decode(_SCRIPT).decode()], capture_output=True, text=True, timeout=300)
    terminalreporter.section("EXP1 pod-side checks")
    for line in (out.stdout + out.stderr).splitlines():
        terminalreporter.write_line("EXP1 " + line)
